ulty":"簡單","description":"香濃暖胃的蔬食咖哩","tags":["蔬食","異國料理"],"ingredients":[{"name":"咖哩塊","amount":"半盒"},{"name":"馬鈴薯","amount":"1顆"},{"name":"紅蘿蔔","amount":"1根"},{"name":"洋蔥","amount":"1顆"}],"steps":[{"description":"洋蔥馬鈴薯紅蘿蔔切塊炒軟"},{"description":"加水燉煮至軟"},{"description":"放入咖哩塊拌至融化"},{"description":"煮至濃稠"}]},{"title":"涼拌豆干(素)","cookTimeMinutes":15,"difficulty":"簡單","description":"清爽開胃的素食涼拌","tags":["蔬食","涼拌"],"ingredients":[{"name":"豆干","amount":"200g"},{"name":"芹菜","amount":"1根"},{"name":"醬油","amount":"1大匙"},{"name":"香油","amount":"1小匙"}],"steps":[{"description":"豆干切絲汆燙放涼"},{"description":"芹菜切絲"},{"description":"調好醬油香油醬汁"},{"description":"拌勻享用"}]},{"title":"蔬食漢堡排","cookTimeMinutes":25,"difficulty":"普通","description":"健康無肉的漢堡排","tags":["蔬食"],"ingredients":[{"name":"素肉末","amount":"200g"},{"name":"洋蔥丁","amount":"適量"},{"name":"麵包粉","amount":"適量"},{"name":"雞蛋","amount":"1顆"}],"steps":[{"description":"所有食材混合拌勻"},{"description":"捏成圓餅狀"},{"description":"平底鍋煎至兩面金黃"},{"description":"搭配麵包享用"}]},{"title":"蔬菜炒烏龍","cookTimeMinutes":15,"difficulty":"簡單","description":"清爽快速的蔬食主食","tags":["蔬食","快速","麵食"],"ingredients":[{"name":"烏龍麵","amount":"1份"},{"name":"高麗菜","amount":"適量"},{"name":"紅蘿蔔絲","amount":"適量"},{"name":"醬油","amount":"1大匙"}],"steps":[{"description":"烏龍麵燙熱備用"},{"description":"炒香蔬菜"},{"description":"加入烏龍麵拌炒"},{"description":"加醬油調味出鍋"}]}]'::jsonb;
begin
  for v_user_id in select id from auth.users loop
    for v_recipe in select * from jsonb_array_elements(v_seed_recipes) loop
      -- skip if this user already has a recipe with this title (safe to re-run)
      if exists (
        select 1 from recipes
        where recipes.user_id = v_user_id and recipes.title = v_recipe->>'title'
      ) then
        continue;
      end if;

      insert into recipes (user_id, title, cook_time_minutes, difficulty, description, tags)
      values (
        v_user_id,
        v_recipe->>'title',
        (v_recipe->>'cookTimeMinutes')::integer,
        v_recipe->>'difficulty',
        v_recipe->>'description',
        (select coalesce(array_agg(tag), '{}') from jsonb_array_elements_text(v_recipe->'tags') as tag)
      )
      returning id into v_recipe_id;

      v_sort_order := 0;
      for v_ingredient in select * from jsonb_array_elements(v_recipe->'ingredients') loop
        insert into recipe_ingredients (recipe_id, name, amount, sort_order)
        values (v_recipe_id, v_ingredient->>'name', v_ingredient->>'amount', v_sort_order);
        v_sort_order := v_sort_order + 1;
      end loop;

      v_sort_order := 0;
      for v_step in select * from jsonb_array_elements(v_recipe->'steps') loop
        insert into recipe_steps (recipe_id, description, sort_order)
        values (v_recipe_id, v_step->>'description', v_sort_order);
        v_sort_order := v_sort_order + 1;
      end loop;
    end loop;
  end loop;
end $$;
